const EXPLAIN = [
  {
    id: 'amplitude', icon: 'α', level: 1, keys: ['amplitúd', 'amplitude', 'амплітуд'], codex: ['amp', 'abs2', 'conj'],
    title: tr('Amplitúda: čo je pod odmocninou', 'Amplitude: what is under the square root', 'Амплітуда: що під коренем'),
    short: tr('Amplitúda je komplexné číslo. Pravdepodobnosť je až jej druhá mocnina.', 'An amplitude is a complex number. Probability is only its squared magnitude.', 'Амплітуда — комплексне число. Ймовірність — лише квадрат її модуля.'),
    body: tr('Amplitúda <b>α</b> hovorí, „koľko“ z daného výsledku v stave je — ale s fázou. Pravdepodobnosť jedného výsledku je <b>P = |α|²</b> (Bornovo pravidlo). Preto α = i dáva rovnakú pravdepodobnosť ako α = 1, hoci fáza je iná.<br><br>Amplitúdy sa <b>sčítavajú pred umocnením</b>. To je celý trik interferencie: dve cesty môžu mať každá P = ¼, a spolu dať 1 alebo 0. Ak by sme sčítavali pravdepodobnosti, interferencia by nikdy nevznikla.', 'The amplitude <b>α</b> says “how much” of an outcome the state contains — but with a phase. The probability of one outcome is <b>P = |α|²</b> (Born’s rule). So α = i gives the same probability as α = 1, although the phase differs.<br><br>Amplitudes <b>add before squaring</b>. That is the whole trick of interference: two paths can each have P = ¼ and together give 1 or 0. If we added probabilities, interference could never appear.', 'Амплітуда <b>α</b> каже, «скільки» даного результату є в стані — але з фазою. Імовірність одного результату — <b>P = |α|²</b> (правило Борна). Тому α = i дає ту саму ймовірність, що й α = 1, хоч фаза різна.<br><br>Амплітуди <b>додаються до піднесення до квадрата</b>. У цьому весь трюк інтерференції: два шляхи можуть мати по P = ¼, а разом дати 1 або 0. Якби ми додавали ймовірності, інтерференція не виникла б ніколи.')
  },
  {
    id: 'phase', icon: 'φ', level: 1, keys: ['fáz', 'phase', 'фаз'], codex: ['eiphi', 'relph', 'globalph'],
    title: tr('Fáza: ručička, ktorá rozhoduje o interferencii', 'Phase: the hand that decides interference', 'Фаза: стрілка, що вирішує інтерференцію'),
    short: tr('Fáza je uhol. Sama o sebe nemení P, ale pri skladaní ciest rozhoduje, či sa amplitúdy sčítajú alebo vyrušia.', 'Phase is an angle. Alone it does not change P, but when paths combine it decides whether amplitudes add or cancel.', 'Фаза — це кут. Сама вона не змінює P, але при складанні шляхів вирішує, чи амплітуди додаються, чи гасяться.'),
    body: tr('Fázu si predstav ako natočenie ručičky hodín v komplexnej rovine. <b>Globálna fáza</b> otočí celý stav; nikto ju nevidí. <b>Relatívna fáza</b> je rozdiel medzi zložkami α a β — a tú vidno pri meraní v inej báze.<br><br>Preto |+⟩ a |−⟩ dávajú v Z-báze rovnakých 50/50, ale H je rozlíši: H|+⟩ = |0⟩, H|−⟩ = |1⟩. Fáza je informácia, ktorá sa dá prečítať interferenciou.', 'Picture phase as the angle of a clock hand in the complex plane. A <b>global phase</b> turns the whole state; nobody can see it. A <b>relative phase</b> is the difference between the α and β components — and that is visible when measuring in another basis.<br><br>That is why |+⟩ and |−⟩ give the same 50/50 in the Z basis, yet H tells them apart: H|+⟩ = |0⟩, H|−⟩ = |1⟩. Phase is information that can be read out by interference.', 'Уяви фазу як кут стрілки годинника в комплексній площині. <b>Глобальна фаза</b> повертає весь стан; її ніхто не бачить. <b>Відносна фаза</b> — це різниця між компонентами α і β, і її видно при вимірюванні в іншому базисі.<br><br>Тому |+⟩ і |−⟩ дають у базисі Z однакові 50/50, але H їх розрізняє: H|+⟩ = |0⟩, H|−⟩ = |1⟩. Фаза — це інформація, яку можна зчитати інтерференцією.')
  },
  {
    id: 'interference', icon: '∿', level: 1, keys: ['interferen', 'interference', 'інтерферен'], codex: ['interf', 'supmix'],
    title: tr('Interferencia: sčítaj amplitúdy, až potom umocni', 'Interference: add amplitudes, then square', 'Інтерференція: додай амплітуди, аж потім піднось до квадрата'),
    short: tr('Dve cesty k rovnakému výsledku sa sčítajú ako komplexné čísla. Fáza rozhodne o zosilnení alebo vyrušení.', 'Two paths to the same outcome add as complex numbers. The phase decides reinforcement or cancellation.', 'Два шляхи до одного результату додаються як комплексні числа. Фаза вирішує підсилення чи гасіння.'),
    body: tr('Ak sa do výsledku dá dostať dvoma cestami, amplitúdy <b>A₁ + A₂</b> sa sčítajú. Pravdepodobnosť je |A₁ + A₂|², nie |A₁|² + |A₂|². Rozdiel je <b>interferenčný člen</b> 2 Re(A₁A₂*), ktorý môže byť kladný, záporný alebo nulový.<br><br>Preto Machov–Zehnderov interferometer s dvoma zhodnými cestami dá jednoznačný výsledok, kým meranie „ktorej cesty“ interferenciu zničí. Interferencia nie je záhada — je to dôsledok toho, že kvantový stav je vektor s fázou.', 'If an outcome can be reached in two ways, the amplitudes <b>A₁ + A₂</b> add. The probability is |A₁ + A₂|², not |A₁|² + |A₂|². The difference is the <b>interference term</b> 2 Re(A₁A₂*), which can be positive, negative or zero.<br><br>That is why a Mach–Zehnder interferometer with two identical paths gives a definite result, while a “which-path” measurement destroys the interference. Interference is not a mystery — it follows from the state being a vector with phase.', 'Якщо до результату можна дійти двома шляхами, амплітуди <b>A₁ + A₂</b> додаються. Імовірність — |A₁ + A₂|², а не |A₁|² + |A₂|². Різниця — <b>інтерференційний член</b> 2 Re(A₁A₂*), який може бути додатним, від’ємним або нульовим.<br><br>Тому інтерферометр Маха–Цендера з двома однаковими шляхами дає однозначний результат, а вимірювання «яким шляхом» інтерференцію руйнує. Інтерференція не загадка — це наслідок того, що квантовий стан є вектором із фазою.')
  },
  {
    id: 'measurement', icon: '🔭', level: 2, keys: ['meran', 'measur', 'вимір'], codex: ['basisq', 'Sz', 'ket0'],
    title: tr('Meranie: otázka, ktorú kladie prístroj', 'Measurement: the question the apparatus asks', 'Вимірювання: питання, яке ставить прилад'),
    short: tr('Meranie nie je „pozretie sa“. Vyberie bázu, dá jeden výsledok a stav zmení na zodpovedajúci vlastný stav.', 'Measurement is not “looking”. It selects a basis, returns one outcome and changes the state to the matching eigenstate.', 'Вимірювання — не «погляд». Воно вибирає базис, дає один результат і змінює стан на відповідний власний стан.'),
    body: tr('Prístroj sa vždy pýta v nejakej <b>báze</b>: „|0⟩, alebo |1⟩?“ alebo „|+⟩, alebo |−⟩?“. Amplitúdy určujú pravdepodobnosti, ale <b>jedno meranie dá len jeden výsledok</b>. Po meraní je stav v tomto výsledku (ak ho nezabudneme), preto opakované meranie v tej istej báze dá to isté.<br><br>„Kolaps“ je pracovný názov pre tento prechod od možností k faktu. Dekoherencia vysvetľuje, prečo ho nevidíme v makrosvete, ale nie je totožná s kolapsom: zmes nie je to isté ako jeden konkrétny výsledok.', 'An apparatus always asks in some <b>basis</b>: “|0⟩ or |1⟩?” or “|+⟩ or |−⟩?”. Amplitudes set the probabilities, but <b>one measurement gives only one outcome</b>. After the measurement the state is the matching outcome (if we do not forget it), so repeating the same measurement gives the same result.<br><br>“Collapse” is a working name for this passage from possibilities to a fact. Decoherence explains why we do not see it in the macroscopic world, but it is not the same as collapse: a mixture is not one definite outcome.', 'Прилад завжди питає в якомусь <b>базисі</b>: «|0⟩ чи |1⟩?» або «|+⟩ чи |−⟩?». Амплітуди задають імовірності, але <b>одне вимірювання дає лише один результат</b>. Після вимірювання стан відповідає цьому результату (якщо ми його не забули), тому повторне вимірювання в тому самому базисі дасть те саме.<br><br>«Колапс» — робоча назва цього переходу від можливостей до факту. Декогеренція пояснює, чому його не видно в макросвіті, але вона не тотожна колапсу: суміш — це не один конкретний результат.')
  },
  {
    id: 'basis', icon: '🧭', level: 2, keys: ['báz', 'basis', 'базис'], codex: ['basisq', 'ket0'],
    title: tr('Báza: súčasť otázky, nie vlastnosť stavu', 'Basis: part of the question, not a property of the state', 'Базис: частина питання, а не властивість стану'),
    short: tr('Ten istý stav vyzerá v rôznych bázach inak. „Istota“ v Z neznamená istotu v X.', 'The same state looks different in different bases. “Certainty” in Z does not mean certainty in X.', 'Той самий стан виглядає в різних базисах по-різному. «Упевненість» у Z не означає впевненості в X.'),
    body: tr('Báza je súbor ortogonálnych stavov, na ktoré sa pýtame. |0⟩ je istý výsledok merania v Z-báze, ale v X-báze je to 50/50 medzi |+⟩ a |−⟩. To nie je rozpor: mení sa otázka, nie stav.<br><br>Preto sa v úlohách vždy pýtame „v akej báze?“ a preto má zmysel hovoriť o <b>relatívnej fáze</b>: je to rozdiel, ktorý sa prejaví až pri zmene bázy. Zmena bázy je unitárna operácia — napríklad H.', 'A basis is a set of orthogonal states we ask about. |0⟩ is a certain outcome in the Z basis, but in the X basis it is 50/50 between |+⟩ and |−⟩. That is no contradiction: the question changes, not the state.<br><br>That is why every task asks “in which basis?” and why <b>relative phase</b> makes sense: it is a difference that shows up only when the basis changes. A change of basis is a unitary operation — for example H.', 'Базис — це набір ортогональних станів, про які ми питаємо. |0⟩ — певний результат у базисі Z, але в базисі X це 50/50 між |+⟩ і |−⟩. Це не суперечність: змінюється питання, а не стан.<br><br>Тому кожне завдання питає «в якому базисі?» і тому має сенс <b>відносна фаза</b>: це різниця, яка проявляється лише при зміні базису. Зміна базису — унітарна операція, наприклад H.')
  },
  {
    id: 'spin', icon: '↕', level: 2, keys: ['spin', 'спін'], codex: ['spinhalf', 'Sz', 'hbar'],
    title: tr('Spin: kvantový moment, nie rotujúca guľôčka', 'Spin: a quantum moment, not a spinning ball', 'Спін: квантовий момент, а не кулька, що обертається'),
    short: tr('Spin ½ má len dve možné projekcie. „Hore“ a „dole“ sú výsledky merania, nie predpripravené šípky.', 'Spin ½ has only two possible projections. “Up” and “down” are measurement outcomes, not pre-existing arrows.', 'Спін ½ має лише дві можливі проєкції. «Вгору» і «вниз» — результати вимірювання, а не заздалегідь готові стрілки.'),
    body: tr('Elektrón má spin ½: v ľubovoľnej zvolenej osi môžeš namerať len +ħ/2 alebo −ħ/2. To neznamená, že pred meraním mal jednu z týchto hodnôt — v kvantovej teórii výsledok vzniká až pri meraní v danej báze.<br><br>Stern–Gerlachova pec meria projekciu spinu na os magnetu. Otoč magnet o 90° a dostaneš inú otázku; preto sa atómy v postupnosti Z → X → Z „preusporiadajú“ tak, ako keby prvé meranie zabudli. To je fyzika, nie chyba prístroja.', 'An electron has spin ½: along any chosen axis you can measure only +ħ/2 or −ħ/2. That does not mean it had one of these values before the measurement — in quantum theory the outcome appears only when measured in that basis.<br><br>A Stern–Gerlach magnet measures the spin projection along its axis. Rotate the magnet by 90° and you ask a different question; that is why atoms in the sequence Z → X → Z “rearrange” as if the first measurement were forgotten. This is physics, not an apparatus error.', 'Електрон має спін ½: уздовж будь-якої обраної осі можна виміряти лише +ħ/2 або −ħ/2. Це не означає, що до вимірювання він мав одне з цих значень — у квантовій теорії результат виникає лише при вимірюванні в цьому базисі.<br><br>Піч Штерна–Ґерлаха вимірює проєкцію спіну на вісь магніту. Поверни магніт на 90° — і ти ставиш інше питання; тому атоми в послідовності Z → X → Z «перевпорядковуються», ніби перше вимірювання забули. Це фізика, а не помилка приладу.')
  },
  {
    id: 'bloch', icon: '🌐', level: 3, keys: ['bloch', 'блох'], codex: ['bloch', 'sphere', 'thetaphi'],
    title: tr('Blochova sféra: mapa jedného qubitu', 'The Bloch sphere: a map of one qubit', 'Сфера Блоха: карта одного кубіта'),
    short: tr('Povrch = čisté stavy, vnútro = zmiešané. Ortogonálne stavy sú na sfére protiľahlé.', 'Surface = pure states, interior = mixed. Orthogonal states are antipodal on the sphere.', 'Поверхня = чисті стани, внутрішність = змішані. Ортогональні стани на сфері протилежні.'),
    body: tr('Každý čistý stav jedného qubitu sa dá nakresliť ako bod na jednotkovej sfére: |0⟩ na severe, |1⟩ na juhu, |±⟩ a |±i⟩ na rovníku. Uhly θ, φ sú súradnice, ale v amplitúdach vystupuje <b>θ/2</b> — preto otočenie o 360° na sfére zodpovedá otočeniu o 720° v stave.<br><br>Zmiešaný stav je bod vnútri; dĺžka vektora |r| < 1 hovorí, koľko koherencie zostalo. Stred je maximálne zmiešaný stav I/2. Blochova sféra je výborná mapa, ale nie je to priestor, v ktorom qubit „naozaj“ sedí.', 'Every pure state of one qubit can be drawn as a point on the unit sphere: |0⟩ at the north pole, |1⟩ at the south, |±⟩ and |±i⟩ on the equator. The angles θ, φ are coordinates, but the amplitudes contain <b>θ/2</b> — that is why a 360° turn on the sphere corresponds to a 720° turn of the state.<br><br>A mixed state is a point inside; the vector length |r| < 1 says how much coherence remains. The centre is the maximally mixed state I/2. The Bloch sphere is an excellent map, but it is not the space where the qubit “really” sits.', 'Кожен чистий стан одного кубіта можна намалювати як точку на одиничній сфері: |0⟩ на півночі, |1⟩ на півдні, |±⟩ і |±i⟩ на екваторі. Кути θ, φ — координати, але в амплітудах є <b>θ/2</b>, тому поворот на 360° на сфері відповідає повороту на 720° у стані.<br><br>Змішаний стан — точка всередині; довжина вектора |r| < 1 каже, скільки когерентності залишилося. Центр — максимально змішаний стан I/2. Сфера Блоха — чудова карта, але не простір, де кубіт «насправді» сидить.')
  },
  {
    id: 'gates', icon: 'H', level: 3, keys: ['hradl', 'gate', 'гейт'], codex: ['H', 'XYZ', 'ST', 'unitary'],
    title: tr('Hradlá: rotácie, ktoré menia otázku', 'Gates: rotations that change the question', 'Гейти: повороти, що змінюють питання'),
    short: tr('Jednoqubitové hradlo je rotácia Blochovej sféry. X preklopí bit, Z fázu, H zmení bázu.', 'A one-qubit gate is a rotation of the Bloch sphere. X flips the bit, Z the phase, H changes the basis.', 'Однокубітний гейт — поворот сфери Блоха. X перевертає біт, Z фазу, H змінює базис.'),
    body: tr('Hradlo je <b>unitárna</b> operácia: je vratné a zachováva normu. Na Blochovej sfére preto pôsobí ako rotácia. X otočí o 180° okolo osi x (|0⟩ ↔ |1⟩), Z okolo z (|+⟩ ↔ |−⟩), H okolo osi medzi x a z (vymení x ↔ z).<br><br>H nie je „zázračné vytvorenie superpozície“: z |0⟩ urobí |+⟩, ale zo |+⟩ urobí |0⟩. Superpozícia je vždy relatívna k báze. S a T sú rotácie okolo z o 90° a 45° — menia fázu, nie populácie v Z-báze.', 'A gate is a <b>unitary</b> operation: it is reversible and preserves the norm. On the Bloch sphere it therefore acts as a rotation. X rotates by 180° about the x axis (|0⟩ ↔ |1⟩), Z about z (|+⟩ ↔ |−⟩), H about the axis between x and z (swapping x ↔ z).<br><br>H is not a “magic superposition maker”: it turns |0⟩ into |+⟩, but also |+⟩ into |0⟩. Superposition is always relative to a basis. S and T are rotations about z by 90° and 45° — they change phase, not populations in the Z basis.', 'Гейт — <b>унітарна</b> операція: оборотна й зберігає норму. На сфері Блоха він діє як поворот. X повертає на 180° навколо осі x (|0⟩ ↔ |1⟩), Z навколо z (|+⟩ ↔ |−⟩), H навколо осі між x і z (міняє x ↔ z).<br><br>H — не «магічний творець суперпозиції»: з |0⟩ він робить |+⟩, але з |+⟩ робить |0⟩. Суперпозиція завжди відносна до базису. S і T — повороти навколо z на 90° і 45°: вони змінюють фазу, а не популяції в базисі Z.')
  },
  {
    id: 'phase-types', icon: '∼', level: 3, keys: ['globáln', 'global phase', 'глобальн', 'relatívn', 'relative phase', 'відносн'], codex: ['globalph', 'relph'],
    title: tr('Globálna vs. relatívna fáza', 'Global vs. relative phase', 'Глобальна vs. відносна фаза'),
    short: tr('Globálna fáza je nepozorovateľná. Relatívna fáza je pozorovateľná a nesie informáciu.', 'Global phase is unobservable. Relative phase is observable and carries information.', 'Глобальна фаза неспостережувана. Відносна фаза спостережувана й несе інформацію.'),
    body: tr('Ak vynásobíš celý stav rovnakým faktorom e<sup>iγ</sup>, nezmení sa žiadna pravdepodobnosť ani interferencia. Preto hovoríme, že stavy líšiace sa globálnou fázou sú fyzikálne totožné (∼).<br><br>Relatívna fáza je rozdiel medzi α a β. |+⟩ = (|0⟩ + |1⟩)/√2 a |−⟩ = (|0⟩ − |1⟩)/√2 majú rovnaké P(0), P(1), ale opačnú relatívnu fázu. Meranie v X-báze (napr. H pred meraním) ich rozlíši. V NMR je práve táto fáza zapísaná v priečnej magnetizácii.', 'If you multiply the whole state by the same factor e<sup>iγ</sup>, no probability or interference changes. That is why states differing by a global phase are physically identical (∼).<br><br>Relative phase is the difference between α and β. |+⟩ = (|0⟩ + |1⟩)/√2 and |−⟩ = (|0⟩ − |1⟩)/√2 have the same P(0), P(1), but opposite relative phase. Measuring in the X basis (e.g. H before measurement) tells them apart. In NMR this phase is exactly what the transverse magnetisation records.', 'Якщо помножити весь стан на той самий множник e<sup>iγ</sup>, жодна ймовірність чи інтерференція не зміниться. Тому стани, що різняться глобальною фазою, фізично тотожні (∼).<br><br>Відносна фаза — різниця між α і β. |+⟩ = (|0⟩ + |1⟩)/√2 і |−⟩ = (|0⟩ − |1⟩)/√2 мають однакові P(0), P(1), але протилежну відносну фазу. Вимірювання в базисі X (наприклад, H перед вимірюванням) їх розрізняє. У ЯМР саме цю фазу фіксує поперечна намагніченість.')
  },
  {
    id: 'superposition-mixture', icon: '⚖', level: 4, keys: ['superpozíc', 'superposition', 'суперпозиц', 'zmes', 'mixture', 'суміш'], codex: ['supmix', 'mix', 'rho'],
    title: tr('Superpozícia vs. zmes: rovnaké štatistiky, iná budúcnosť', 'Superposition vs. mixture: same statistics, different future', 'Суперпозиція vs. суміш: та сама статистика, інше майбутнє'),
    short: tr('V Z-báze môžu vyzerať rovnako. Len superpozícia však interferuje — H·H dá |0⟩ s istotou.', 'In the Z basis they can look identical. Only a superposition interferes — H·H gives |0⟩ with certainty.', 'У базисі Z вони можуть виглядати однаково. Лише суперпозиція інтерферує — H·H дає |0⟩ напевно.'),
    body: tr('Stav |+⟩ = (|0⟩ + |1⟩)/√2 a zmes 50 % |0⟩ + 50 % |1⟩ dávajú v Z-báze rovnaké výsledky. Rozdiel sa prejaví pri ďalšom hradle: H|+⟩ = |0⟩ (interferencia ciest), kým zmes po H zostane 50/50.<br><br>Matematicky: superpozícia má mimodiagonálne prvky ρ, zmes nie. Preto sa zmes nedá použiť na kvantové algoritmy — chýba jej koherencia, ktorá umožňuje interferenciu. „Neviem, v ktorom stave je“ je klasická zmes, nie superpozícia.', 'The state |+⟩ = (|0⟩ + |1⟩)/√2 and the mixture 50 % |0⟩ + 50 % |1⟩ give the same results in the Z basis. The difference appears at the next gate: H|+⟩ = |0⟩ (interference of paths), whereas the mixture after H stays 50/50.<br><br>Mathematically: a superposition has off-diagonal elements of ρ, a mixture does not. That is why a mixture cannot power quantum algorithms — it lacks the coherence that enables interference. “I don’t know which state it is in” is a classical mixture, not a superposition.', 'Стан |+⟩ = (|0⟩ + |1⟩)/√2 і суміш 50 % |0⟩ + 50 % |1⟩ дають у базисі Z однакові результати. Різниця з’являється на наступному гейті: H|+⟩ = |0⟩ (інтерференція шляхів), тоді як суміш після H лишається 50/50.<br><br>Математично: суперпозиція має позадіагональні елементи ρ, суміш — ні. Тому суміш не може живити квантові алгоритми — їй бракує когерентності, що уможливлює інтерференцію. «Не знаю, в якому він стані» — це класична суміш, а не суперпозиція.')
  },
  {
    id: 'density-matrix', icon: 'ρ', level: 4, keys: ['matic', 'density matrix', 'матриц', 'ρ'], codex: ['rho', 'dagger', 'coh'],
    title: tr('Matica hustoty ρ: stav aj so zmesami', 'The density matrix ρ: states including mixtures', 'Матриця густини ρ: стани разом із сумішами'),
    short: tr('Diagonála = populácie, mimodiagonála = koherencie. ρ je najvšeobecnejší opis stavu.', 'Diagonal = populations, off-diagonal = coherences. ρ is the most general description of a state.', 'Діагональ = популяції, позадіагональ = когерентності. ρ — найзагальніший опис стану.'),
    body: tr('Pre čistý stav |ψ⟩ je ρ = |ψ⟩⟨ψ| projektor. Pre zmes vážený súčet projektorov. Vždy platí Tr ρ = 1, ρ = ρ† a ρ ≥ 0. Čistota je Tr ρ²: pre čistý stav 1, pre maximálne zmiešaný 1/2.<br><br>V báze Z sú ρ₀₀, ρ₁₁ pravdepodobnosti a ρ₀₁ = ρ₁₀* koherencia. Unitárna evolúcia ρ′ = UρU† otáča Blochov vektor a nemení |r|; dekoherencia zmenšuje mimodiagonálu a tým aj |r|. Stredná hodnota je ⟨A⟩ = Tr(ρA).', 'For a pure state |ψ⟩, ρ = |ψ⟩⟨ψ| is a projector. For a mixture it is a weighted sum of projectors. Always Tr ρ = 1, ρ = ρ† and ρ ≥ 0. Purity is Tr ρ²: 1 for a pure state, 1/2 for the maximally mixed state.<br><br>In the Z basis, ρ₀₀ and ρ₁₁ are probabilities and ρ₀₁ = ρ₁₀* is the coherence. Unitary evolution ρ′ = UρU† rotates the Bloch vector and keeps |r|; decoherence shrinks the off-diagonal and therefore |r|. The expectation value is ⟨A⟩ = Tr(ρA).', 'Для чистого стану |ψ⟩ ρ = |ψ⟩⟨ψ| є проєктором. Для суміші — зважена сума проєкторів. Завжди Tr ρ = 1, ρ = ρ† і ρ ≥ 0. Чистота — Tr ρ²: 1 для чистого стану, 1/2 для максимально змішаного.<br><br>У базисі Z ρ₀₀ і ρ₁₁ — імовірності, а ρ₀₁ = ρ₁₀* — когерентність. Унітарна еволюція ρ′ = UρU† обертає вектор Блоха й не змінює |r|; декогеренція зменшує позадіагональ, а отже й |r|. Середнє значення — ⟨A⟩ = Tr(ρA).')
  },
  {
    id: 'decoherence', icon: '🌫', level: 4, keys: ['dekoheren', 'decoheren', 'декогерен'], codex: ['deco', 'coh', 'mix'],
    title: tr('Dekoherencia: ako prostredie maže fázu', 'Decoherence: how the environment erases phase', 'Декогеренція: як середовище стирає фазу'),
    short: tr('Prostredie sa zapletie so stavom a koherencie zmiznú. Stav sa zmení na zmes, ale konkrétny výsledok ešte nie je vybraný.', 'The environment entangles with the state and coherences vanish. The state becomes a mixture, but no definite outcome is selected yet.', 'Середовище заплутується зі станом, і когерентності зникають. Стан стає сумішшю, але конкретний результат ще не обраний.'),
    body: tr('Kvantový systém nikdy nie je úplne izolovaný. Molekuly vzduchu, fotóny či tepelné fluktuácie „odmerajú“ fázu a informácia unikne do prostredia. Pre nás sa koherencie stratia a stav vyzerá ako klasická zmes.<br><br>Dekoherencia je veľmi rýchla (často zlomky sekundy v makroskopických objektoch), preto kvantové počítače potrebujú chladenie a izoláciu. Dôležité: dekoherencia <b>nevysvetľuje sama</b>, prečo vidíme jeden konkrétny výsledok — vysvetľuje, prečo už nevidíme interferenciu.', 'A quantum system is never perfectly isolated. Air molecules, photons or thermal fluctuations “measure” the phase and the information leaks into the environment. To us the coherences disappear and the state looks like a classical mixture.<br><br>Decoherence is very fast (often fractions of a second in macroscopic objects), which is why quantum computers need cooling and isolation. Importantly, decoherence <b>does not by itself explain</b> why we see one definite outcome — it explains why we no longer see interference.', 'Квантова система ніколи не є ідеально ізольованою. Молекули повітря, фотони чи теплові флуктуації «вимірюють» фазу, і інформація витікає в середовище. Для нас когерентності зникають, і стан виглядає як класична суміш.<br><br>Декогеренція дуже швидка (часто частки секунди в макроскопічних об’єктах), тому квантові комп’ютери потребують охолодження та ізоляції. Важливо: декогеренція <b>сама не пояснює</b>, чому ми бачимо один конкретний результат — вона пояснює, чому ми вже не бачимо інтерференції.')
  },
  {
    id: 'braket', icon: '⟨ψ|', level: 5, keys: ['bra-ket', 'braket', 'ket', 'bra', 'бра-кет', 'кет'], codex: ['ket', 'bra', 'braket', 'ketbra', 'expect'],
    title: tr('Bra-ket: gramatika kvantových výrazov', 'Bra-ket: the grammar of quantum expressions', 'Bra-ket: граматика квантових виразів'),
    short: tr('Ket je stav, bra je otázka, ⟨φ|ψ⟩ je číslo, |ψ⟩⟨φ| je operátor. Poradie určuje typ.', 'A ket is a state, a bra is a question, ⟨φ|ψ⟩ is a number, |ψ⟩⟨φ| is an operator. Order determines the type.', 'Ket — стан, bra — питання, ⟨φ|ψ⟩ — число, |ψ⟩⟨φ| — оператор. Порядок визначає тип.'),
    body: tr('|ψ⟩ je stĺpcový vektor, ⟨ψ| je jeho hermitovsky združený riadok. Súčin ⟨φ|ψ⟩ je <b>komplexné číslo</b> — amplitúda prekrytia. Jeho druhá mocnina |⟨φ|ψ⟩|² je pravdepodobnosť.<br><br>Opačné poradie |ψ⟩⟨φ| je <b>matica</b> (operátor). |ψ⟩⟨ψ| je projektor na stav ψ. Strieška (Â) znamená operátor pozorovateľnej veličiny. Keď sa v zadaní pýtajú „aký typ výrazu to je?“, rozhoduje práve poradie a to, či je výsledok číslo, vektor alebo matica.', '|ψ⟩ is a column vector, ⟨ψ| is its Hermitian-conjugate row. The product ⟨φ|ψ⟩ is a <b>complex number</b> — the overlap amplitude. Its squared magnitude |⟨φ|ψ⟩|² is a probability.<br><br>The reverse order |ψ⟩⟨φ| is a <b>matrix</b> (operator). |ψ⟩⟨ψ| is the projector onto ψ. A hat (Â) denotes an operator of an observable. When a task asks “what type of expression is this?”, the order and whether the result is a number, vector or matrix decide it.', '|ψ⟩ — стовпцевий вектор, ⟨ψ| — ермітово-спряжений рядок. Добуток ⟨φ|ψ⟩ — <b>комплексне число</b>, амплітуда перекриття. Його квадрат модуля |⟨φ|ψ⟩|² — імовірність.<br><br>Зворотний порядок |ψ⟩⟨φ| — <b>матриця</b> (оператор). |ψ⟩⟨ψ| — проєктор на стан ψ. Дужка (Â) позначає оператор спостережуваної. Коли в завданні питають «який це тип виразу?», вирішують саме порядок і те, чи результат є числом, вектором чи матрицею.')
  },
  {
    id: 'nmr', icon: '🧪', level: 6, keys: ['nmr', 'nukleárn', 'ядерн', 'ямр'], codex: ['rabi', 'zeeman', 'B0', 'ensemble'],
    title: tr('NMR: qubit v molekule', 'NMR: a qubit inside a molecule', 'ЯМР: кубіт у молекулі'),
    short: tr('NMR meria obrovský ansámbel spinov. Jeden bit nevidno — vidno strednú hodnotu magnetizácie.', 'NMR measures a huge ensemble of spins. A single bit is invisible — we see the average magnetisation.', 'ЯМР вимірює величезний ансамбль спінів. Один біт не видно — видно середню намагніченість.'),
    body: tr('V NMR je qubit jadro s polovičným spinom (napr. ¹H alebo ³¹P) v silnom poli B₀. Pole vytvorí dve energetické hladiny; prechod medzi nimi má frekvenciu ν₀ = γB₀/2π. RF cievka vysiela impulzy na tejto frekvencii a meria priečnu magnetizáciu.<br><br>Pretože je molekúl obrovské množstvo, signál je priemer. To je výhoda (silný signál), ale aj obmedzenie: nevidíme jednotlivé výsledky, len stredné hodnoty. Napriek tomu NMR ako prvé ukázalo, že sa dá počítať s kvantovými stavmi (pseudo-čistý stav).', 'In NMR the qubit is a half-integer nucleus (e.g. ¹H or ³¹P) in a strong field B₀. The field creates two energy levels; the transition frequency is ν₀ = γB₀/2π. An RF coil sends pulses at that frequency and measures the transverse magnetisation.<br><br>Because there are enormous numbers of molecules, the signal is an average. That is an advantage (a strong signal) but also a limitation: we do not see individual outcomes, only mean values. Even so, NMR was the first to show that quantum states can compute (the pseudo-pure state).', 'У ЯМР кубіт — ядро з напівцілим спіном (наприклад, ¹H або ³¹P) у сильному полі B₀. Поле створює два енергетичні рівні; частота переходу ν₀ = γB₀/2π. РЧ-котушка надсилає імпульси на цій частоті й вимірює поперечну намагніченість.<br><br>Оскільки молекул величезна кількість, сигнал є середнім. Це перевага (сильний сигнал), але й обмеження: ми не бачимо окремих результатів, лише середні значення. Попри це, ЯМР першим показав, що квантовими станами можна обчислювати (псевдочистий стан).')
  },
  {
    id: 'precession', icon: '↻', level: 6, keys: ['preces', 'precession', 'прецес'], codex: ['precess', 'B0'],
    title: tr('Precesia: fáza sa točí, pravdepodobnosti nie', 'Precession: phase turns, probabilities do not', 'Прецесія: фаза обертається, ймовірності — ні'),
    short: tr('V poli B₀ sa relatívna fáza vyvíja ako rotácia. P(0) a P(1) zostávajú rovnaké.', 'In a B₀ field the relative phase evolves as a rotation. P(0) and P(1) stay the same.', 'У полі B₀ відносна фаза еволюціонує як обертання. P(0) і P(1) залишаються однаковими.'),
    body: tr('Hamiltonián H = −γB₀S_z/to dáva energetickým hladinám |0⟩ a |1⟩ rôzne fázy. Rozdiel fáz rastie lineárne s časom, takže Blochov vektor rotuje okolo osi z. V Z-báze sa pritom nemení ani P(0), ani P(1) — mení sa len relatívna fáza.<br><br>Preto samotná precesia nenapíše do qubitu čitateľnú informáciu v Z-báze; treba ju prečítať interferenciou (ďalší impulz alebo meranie v X-báze). V NMR je precesia základ FID signálu.', 'The Hamiltonian H = −γB₀S_z/ħ gives the energy levels |0⟩ and |1⟩ different phases. The phase difference grows linearly in time, so the Bloch vector rotates about the z axis. In the Z basis neither P(0) nor P(1) changes — only the relative phase does.<br><br>Precession alone therefore does not write readable information into the qubit in the Z basis; it must be read by interference (another pulse or a measurement in the X basis). In NMR precession is the basis of the FID signal.', 'Гамільтоніан H = −γB₀S_z/ħ дає енергетичним рівням |0⟩ і |1⟩ різні фази. Різниця фаз зростає лінійно з часом, тому вектор Блоха обертається навколо осі z. У базисі Z при цьому не змінюються ні P(0), ні P(1) — змінюється лише відносна фаза.<br><br>Тому сама прецесія не записує в кубіт читабельну інформацію в базисі Z; її треба зчитати інтерференцією (ще один імпульс або вимірювання в базисі X). У ЯМР прецесія — основа сигналу FID.')
  },
  {
    id: 'pulse', icon: '〰', level: 6, keys: ['impulz', 'pulse', 'імпульс', 'π/2', 'π-impulz'], codex: ['OmegaR', 'rabiosc', 'rotframe'],
    title: tr('RF impulz: otočenie o zvolený uhol', 'RF pulse: a rotation by a chosen angle', 'РЧ-імпульс: поворот на обраний кут'),
    short: tr('Plocha impulzu Ω_R·t je uhol otočenia. π preklopí, π/2 dostane stav na rovník.', 'The pulse area Ω_R·t is the rotation angle. π flips, π/2 brings the state to the equator.', 'Площа імпульсу Ω_R·t — кут повороту. π перевертає, π/2 виводить стан на екватор.'),
    body: tr('Krátky RF impulz v rezonancii pôsobí ako rotácia okolo osi v rovine xy. Uhol je daný plochou impulzu θ = Ω_R·t, kde Ω_R je Rabiho frekvencia. Preto π-impulz preklopí |0⟩ na |1⟩ a π/2 vytvorí |+⟩.<br><br>V praxi sa plocha kalibruje: nájde sa dĺžka impulzu, ktorá dá maximum signálu (π/2), a π-impulz je dvojnásobok. Fázový posun impulzu určuje os rotácie — tak sa robia hradlá X, Y aj fázové operácie.', 'A short resonant RF pulse acts as a rotation about an axis in the xy plane. The angle is set by the pulse area θ = Ω_R·t, where Ω_R is the Rabi frequency. Hence a π pulse flips |0⟩ to |1⟩ and a π/2 pulse creates |+⟩.<br><br>In practice the area is calibrated: find the pulse length that gives the maximum signal (π/2), and the π pulse is twice that. The pulse phase sets the rotation axis — that is how X, Y and phase gates are implemented.', 'Короткий резонансний РЧ-імпульс діє як поворот навколо осі в площині xy. Кут задає площа імпульсу θ = Ω_R·t, де Ω_R — частота Рабі. Тому π-імпульс перевертає |0⟩ на |1⟩, а π/2 створює |+⟩.<br><br>На практиці площу калібрують: знаходять тривалість імпульсу, що дає максимум сигналу (π/2), а π-імпульс — удвічі довший. Фаза імпульсу задає вісь повороту — так реалізують гейти X, Y і фазові операції.')
  },
  {
    id: 'entanglement', icon: '🔗', level: 7, keys: ['previazan', 'entangle', 'сплутан', 'заплутан'], codex: ['entangle', 'phiplus', 'cnot', 'bell'],
    title: tr('Previazanosť: celok, ktorý sa nedá rozložiť', 'Entanglement: a whole that cannot be factored', 'Сплутаність: ціле, яке не можна розкласти'),
    short: tr('Previazaný stav sa nedá zapísať ako súčin stavov častí. Korelácie sú silnejšie než klasické.', 'An entangled state cannot be written as a product of the parts. Its correlations are stronger than classical ones.', 'Сплутаний стан не можна записати як добуток станів частин. Кореляції сильніші за класичні.'),
    body: tr('Bellov stav |Φ⁺⟩ = (|00⟩ + |11⟩)/√2 nie je „prvý qubit v stave 0 a druhý v 0, alebo oba v 1“. Skús ho zapísať ako (a|0⟩+b|1⟩)⊗(c|0⟩+d|1⟩) — nikdy to nevyjde. Práve preto nemá jednotlivý qubit vlastnú Blochovu šípku.<br><br>Korelácie sa prejavia až pri porovnaní meraní. Ak Alice zmeria 0, Bob uvidí 0; ak 1, Bob uvidí 1. To však neumožňuje poslať správu, pretože Bob sám vidí 50/50, kým sa nedozvie Alicin výsledok. Previazanosť je zdroj pre kvantovú teleportáciu, kryptografiu a CHSH.', 'The Bell state |Φ⁺⟩ = (|00⟩ + |11⟩)/√2 is not “the first qubit is 0 and the second is 0, or both are 1”. Try to write it as (a|0⟩+b|1⟩)⊗(c|0⟩+d|1⟩) — it never works. That is exactly why an individual qubit has no Bloch arrow of its own.<br><br>The correlations appear only when measurements are compared. If Alice measures 0, Bob sees 0; if 1, Bob sees 1. This still cannot send a message, because Bob alone sees 50/50 until he learns Alice’s result. Entanglement powers quantum teleportation, cryptography and CHSH.', 'Стан Белла |Φ⁺⟩ = (|00⟩ + |11⟩)/√2 — це не «перший кубіт у стані 0, а другий у 0, або обидва в 1». Спробуй записати його як (a|0⟩+b|1⟩)⊗(c|0⟩+d|1⟩) — ніколи не вийде. Саме тому окремий кубіт не має власної стрілки Блоха.<br><br>Кореляції проявляються лише при порівнянні вимірювань. Якщо Аліса виміряє 0, Боб побачить 0; якщо 1, Боб побачить 1. Але це не дає змоги передати повідомлення, бо Боб сам бачить 50/50, доки не дізнається результат Аліси. Сплутаність живить квантову телепортацію, криптографію та CHSH.')
  },
  {
    id: 'chsh', icon: '75 %', level: 7, keys: ['chsh', 'bellov', 'bell inequal', 'нерівн'], codex: ['chsh', 'bell'],
    title: tr('CHSH: kde sa končia klasické korelácie', 'CHSH: where classical correlations end', 'CHSH: де закінчуються класичні кореляції'),
    short: tr('Lokálna klasická stratégia vyhrá najviac 75 %. Previazané qubity dosiahnu približne 85 %.', 'A local classical strategy wins at most 75 %. Entangled qubits reach about 85 %.', 'Локальна класична стратегія виграє щонайбільше 75 %. Сплутані кубіти сягають близько 85 %.'),
    body: tr('V CHSH hre Alice a Bob dostanú otázky x, y ∈ {0,1} a musia dať odpovede a, b tak, aby a ⊕ b = x·y. Bez komunikácie a s vopred určenými hodnotami (lokálny realismus) sa dá uspieť najviac v 75 % prípadov.<br><br>Ak zdieľajú Bellov stav a merajú vhodne zvolené uhly, uspejú v cos²(π/8) ≈ 85,4 %. Experimenty (Aspect, Clauser, Zeilinger) to potvrdili; Nobelova cena 2022. Nejde o porušenie relativity — len o to, že korelácie nie sú lokálne predurčené.', 'In the CHSH game Alice and Bob receive questions x, y ∈ {0,1} and must answer a, b so that a ⊕ b = x·y. Without communication and with pre-existing values (local realism), they can succeed at most 75 % of the time.<br><br>If they share a Bell state and measure at suitably chosen angles, they succeed with cos²(π/8) ≈ 85.4 %. Experiments (Aspect, Clauser, Zeilinger) confirmed this; the 2022 Nobel Prize. It does not violate relativity — it only shows that the correlations are not locally predetermined.', 'У грі CHSH Аліса й Боб отримують питання x, y ∈ {0,1} і мають дати відповіді a, b так, щоб a ⊕ b = x·y. Без комунікації та з наперед заданими значеннями (локальний реалізм) можна досягти щонайбільше 75 %.<br><br>Якщо вони поділяють стан Белла й вимірюють під доцільно обраними кутами, успіх становить cos²(π/8) ≈ 85,4 %. Експерименти (Аспе, Клаузер, Цайлінгер) це підтвердили; Нобелівська премія 2022. Це не порушує теорію відносності — лише показує, що кореляції не є локально зумовленими.')
  },
  {
    id: 'no-signal', icon: '📵', level: 7, keys: ['signál', 'signal', 'сигнал', 'nesignal'], codex: ['nosignal', 'entangle'],
    title: tr('Nemožnosť signalizácie: prečo previazanosť neposiela správy', 'No-signalling: why entanglement cannot send messages', 'Неможливість сигналізації: чому сплутаність не передає повідомлень'),
    short: tr('Bob vidí 50/50 bez ohľadu na to, čo Alice robí. Korelácie sa objavia až po porovnaní výsledkov.', 'Bob sees 50/50 no matter what Alice does. Correlations appear only after comparing results.', 'Боб бачить 50/50 незалежно від того, що робить Аліса. Кореляції з’являються лише після порівняння результатів.'),
    body: tr('Ak Alice meria svoj qubit z Bellovho stavu, jej výsledok je náhodný. Bobov lokálny stav je pred porovnaním vždy maximálne zmiešaný — bez ohľadu na to, akú bázu Alice zvolila. Preto z jeho samotných meraní nemožno zistiť, či Alice niečo urobila.<br><br>Toto „no-signalling“ je základný princíp: previazanosť mení korelácie, nie marginálne pravdepodobnosti. Keby sa dala použiť na nadsvetelnú komunikáciu, relativity by sa rozpadla. Preto sa kvantové protokoly vždy musia dorozumieť klasickým kanálom.', 'If Alice measures her qubit from a Bell state, her outcome is random. Bob’s local state before comparison is always maximally mixed — regardless of which basis Alice chose. From his own measurements alone he therefore cannot tell whether Alice did anything.<br><br>This “no-signalling” is a fundamental principle: entanglement changes correlations, not marginal probabilities. If it could be used for faster-than-light communication, relativity would collapse. That is why quantum protocols always need a classical channel as well.', 'Якщо Аліса вимірює свій кубіт зі стану Белла, її результат випадковий. Локальний стан Боба до порівняння завжди максимально змішаний — незалежно від того, який базис обрала Аліса. Тому з його власних вимірювань не можна зрозуміти, чи Аліса щось робила.<br><br>Ця «неможливість сигналізації» — фундаментальний принцип: сплутаність змінює кореляції, а не граничні ймовірності. Якби нею можна було передавати надсвітлові повідомлення, теорія відносності зазнала б краху. Тому квантові протоколи завжди потребують і класичного каналу.')
  },
  {
    id: 'complementarity', icon: '☯', level: 8, keys: ['komplementar', 'complementar', 'доповнювальн', 'interpretác', 'interpretation', 'інтерпретац'], codex: ['bohr', 'kant', 'wittg', 'bohm'],
    title: tr('Komplementarita a interpretácie: čo vlastne tvrdíme', 'Complementarity and interpretations: what we actually claim', 'Доповнювальність та інтерпретації: що ми насправді твердимо'),
    short: tr('Kvantová teória dobre predpovedá. Spor je o tom, čo znamená „stav“ a „meranie“ — nie o rovniciach.', 'Quantum theory predicts well. The dispute is about what “state” and “measurement” mean — not about the equations.', 'Квантова теорія добре передбачає. Суперечка про те, що означають «стан» і «вимірювання», а не про рівняння.'),
    body: tr('Bohrova komplementarita: jav opisujeme spolu s experimentálnymi podmienkami; vlnový a časticový opis sa dopĺňajú, nie sú to dva súčasné obrazy. Kodaňská interpretácia je praktická, ale nie je jediná.<br><br>Mnohosvetová interpretácia berie vlnovú funkciu vážne a kolaps nepotrebuje. Bohmova teória je deterministická, ale nelokálna. Objektívny kolaps mení fyziku pri určitej veľkosti. Relačné a QBistické pohľady berú stav ako informáciu, nie ako vlastnosť sveta. Dôležité: experimenty dnes medzi interpretáciami nerozhodujú — rozhodujú o predpovediach, a tie sú rovnaké.', 'Bohr’s complementarity: a phenomenon is described together with the experimental conditions; wave and particle descriptions complement each other, they are not two simultaneous pictures. The Copenhagen interpretation is practical, but not the only one.<br><br>Many-worlds takes the wave function seriously and needs no collapse. Bohm’s theory is deterministic but non-local. Objective-collapse models change the physics at a certain scale. Relational and QBist views treat the state as information, not as a property of the world. Crucially, experiments today do not decide between interpretations — they decide predictions, and those agree.', 'Доповнювальність Бора: явище описуємо разом з експериментальними умовами; хвильовий і частинковий описи доповнюють один одного, це не два одночасні образи. Копенгагенська інтерпретація практична, але не єдина.<br><br>Багатосвітова інтерпретація ставиться до хвильової функції серйозно й не потребує колапсу. Теорія Бома детерміністична, але нелокальна. Моделі об’єктивного колапсу змінюють фізику на певному масштабі. Реляційні та QBist-погляди трактують стан як інформацію, а не як властивість світу. Важливо: експерименти сьогодні не вирішують між інтерпретаціями — вони вирішують передбачення, а вони збігаються.')
  },
  {
    id: 'purity', icon: '◐', level: 10, keys: ['čistot', 'purity', 'purif', 'чистот', 'очищ'], codex: ['unitary', 'mix', 'rho'],
    title: tr('Čistota a purifikácia: ako vrátiť stav na povrch', 'Purity and purification: how to bring a state back to the surface', 'Чистота й очищення: як повернути стан на поверхню'),
    short: tr('Unitárna operácia |r| nemení. Purifikácia je meranie so známym výsledkom alebo chladenie.', 'A unitary operation keeps |r|. Purification is a measurement with a known result, or cooling.', 'Унітарна операція не змінює |r|. Очищення — вимірювання з відомим результатом або охолодження.'),
    body: tr('Čistota stavu je Tr ρ² = (1 + |r|²)/2. Unitárna evolúcia ρ′ = UρU† je rotácia, preto |r| a čistota zostávajú. Dekoherencia |r| zmenšuje — stav sa posúva dovnútra sféry.<br><br>Purifikácia znamená, že sa o stave dozvieme viac: meranie s výsledkom, ktorý poznáme, alebo ochladenie na základný stav. V NMR sa používa <b>pseudo-čistý stav</b>: ansámbel je zmiešaný, ale signál sa správa ako z čistého stavu s malou efektívnou polarizáciou. To je dôvod, prečo NMR „vidí“ kvantové interferencie aj pri izbovej teplote.', 'The purity of a state is Tr ρ² = (1 + |r|²)/2. Unitary evolution ρ′ = UρU† is a rotation, so |r| and purity stay the same. Decoherence shrinks |r| — the state moves inside the sphere.<br><br>Purification means learning more about the state: a measurement with a known outcome, or cooling to the ground state. NMR uses a <b>pseudo-pure state</b>: the ensemble is mixed, but the signal behaves like a pure state with a small effective polarisation. That is why NMR can “see” quantum interference even at room temperature.', 'Чистота стану — Tr ρ² = (1 + |r|²)/2. Унітарна еволюція ρ′ = UρU† є поворотом, тому |r| і чистота зберігаються. Декогеренція зменшує |r| — стан зсувається всередину сфери.<br><br>Очищення означає, що ми дізнаємося більше про стан: вимірювання з відомим результатом або охолодження до основного стану. У ЯМР використовують <b>псевдочистий стан</b>: ансамбль змішаний, але сигнал поводиться як із чистого стану з малою ефективною поляризацією. Саме тому ЯМР «бачить» квантову інтерференцію навіть за кімнатної температури.')
  },
  {
    id: 'mid-circuit', icon: '⏸', level: 11, keys: ['mid-circuit', 'uprostred obvodu', 'mid circuit', 'посеред схеми', 'зворотн'], codex: ['basisq', 'cnot', 'phiplus'],
    title: tr('Meranie uprostred obvodu a spätná väzba', 'Mid-circuit measurement and feedback', 'Вимірювання посеред схеми та зворотний зв’язок'),
    short: tr('Meranie v strede obvodu zmení stav a výsledok sa dá použiť na ďalšie hradlo. To je „measure → decide“.', 'A mid-circuit measurement changes the state, and its result can control later gates. That is “measure → decide”.', 'Вимірювання посеред схеми змінює стан, і його результат можна використати для наступних гейтів. Це «виміряй → виріши».'),
    body: tr('V kvantovom obvode nemusí byť meranie len na konci. Ak zmeriaš qubit uprostred, stav sa zmení na výsledok a ďalšie hradlá môžu závisieť od tohto bitu. Tak vzniká klasická spätná väzba: „ak padlo 1, urob X“.<br><br>To je silný nástroj (korekcia chýb, adaptívne algoritmy), ale aj past: meranie zničí koherenciu, ktorú by si inak mohol využiť. Preto sa meranie v strede používa len vtedy, keď je jeho výsledok naozaj potrebný. V Bellovom stave meranie jedného qubitu okamžite určí koreláciu druhého, ale nie správu.', 'In a quantum circuit, measurement need not be only at the end. If you measure a qubit mid-circuit, the state changes to the outcome and later gates can depend on that bit. This is classical feedback: “if it was 1, apply X”.<br><br>It is a powerful tool (error correction, adaptive algorithms) but also a trap: measurement destroys coherence you might otherwise use. Mid-circuit measurement is therefore used only when its result is genuinely needed. In a Bell state, measuring one qubit immediately fixes the correlation of the other, but not a message.', 'У квантовій схемі вимірювання не обов’язково лише в кінці. Якщо виміряти кубіт посеред схеми, стан зміниться на результат, і наступні гейти можуть залежати від цього біта. Так виникає класичний зворотний зв’язок: «якщо випало 1, застосуй X».<br><br>Це потужний інструмент (корекція помилок, адаптивні алгоритми), але й пастка: вимірювання руйнує когерентність, яку інакше можна було б використати. Тому вимірювання посеред схеми застосовують лише тоді, коли його результат справді потрібен. У стані Белла вимірювання одного кубіта одразу фіксує кореляцію іншого, але не повідомлення.')
  },
  {
    id: 'qft', icon: '∑', level: 15, keys: ['fourier', 'qft', 'dft', 'фур’є', 'фурє'], codex: ['interf'],
    title: tr('Kvantová Fourierova transformácia: z času do frekvencie', 'The quantum Fourier transform: from time to frequency', 'Квантове перетворення Фур’є: з часу в частоту'),
    short: tr('QFT je zmena bázy na bázu frekvencií. V obvode ju tvoria H a riadené fázové hradlá.', 'The QFT is a change of basis to the frequency basis. In a circuit it is built from H and controlled phase gates.', 'QFT — це зміна базису на базис частот. У схемі її складають H і керовані фазові гейти.'),
    body: tr('Klasická DFT rozloží signál na frekvencie v O(N²) operáciách. QFT robí to isté s amplitúdami v O(n²) hradlách pre N = 2ⁿ. Nie je to „rýchlejší Fourier“ na čítanie spektra: výsledok je kvantový stav, z ktorého treba vzorkovať.<br><br>QFT je unitárna zmena bázy. H vytvorí superpozíciu, riadené fázy zapíšu relatívne fázy úmerné súčinu bitov. V Shorovom algoritme QFT prevedie periódu do ostrých frekvenčných špičiek; meranie potom dá odhad periódy. Inverzná QFT je jej adjungovaná operácia.', 'The classical DFT splits a signal into frequencies in O(N²) operations. The QFT does the same to amplitudes in O(n²) gates for N = 2ⁿ. It is not a “faster Fourier” for reading a spectrum: the result is a quantum state that must be sampled.<br><br>The QFT is a unitary change of basis. H creates superpositions, controlled phases record relative phases proportional to products of bits. In Shor’s algorithm the QFT turns a period into sharp frequency peaks; measurement then estimates the period. The inverse QFT is its adjoint.', 'Класичне DFT розкладає сигнал на частоти за O(N²) операцій. QFT робить те саме з амплітудами за O(n²) гейтів для N = 2ⁿ. Це не «швидший Фур’є» для читання спектра: результат — квантовий стан, який треба семплувати.<br><br>QFT — унітарна зміна базису. H створює суперпозиції, керовані фази записують відносні фази, пропорційні добуткам бітів. У алгоритмі Шора QFT перетворює період на гострі частотні піки; вимірювання дає оцінку періоду. Обернене QFT — її спряжена операція.')
  },
  {
    id: 'grover', icon: '🔍', level: 16, keys: ['grover', 'amplitude amplification', 'гровер', 'підсилен'], codex: ['interf'],
    title: tr('Grover: zosilnenie správnej odpovede', 'Grover: amplifying the right answer', 'Ґровер: підсилення правильної відповіді'),
    short: tr('Grover nehľadá všetky položky naraz. Opakovane otáča amplitúdy tak, aby sa správna odpoveď zosilnila.', 'Grover does not search all items at once. It repeatedly rotates amplitudes so the right answer grows.', 'Ґровер не шукає всі елементи одразу. Він повторно обертає амплітуди, щоб правильна відповідь підсилилася.'),
    body: tr('Groverov algoritmus začína rovnomernou superpozíciou všetkých N možností. Orákulum označí správnu odpoveď fázou −1 (fázový spätný ráz), potom „difúzny operátor“ odrazí amplitúdy okolo priemeru. Po ~√N opakovaniach je pravdepodobnosť správnej odpovede blízka 1.<br><br>Zrýchlenie je kvadratické: N = 10⁶ potrebuje ~1000 krokov namiesto 500 000. Nie je to exponenciálne a neporušuje dolné hranice — je to dôsledok interferencie, nie paralelného „vyskúšania všetkého“.', 'Grover’s algorithm starts with a uniform superposition of all N possibilities. An oracle marks the right answer with a phase −1 (phase kickback), then a “diffusion operator” reflects the amplitudes about their mean. After ~√N repetitions the probability of the right answer is close to 1.<br><br>The speed-up is quadratic: N = 10⁶ needs ~1000 steps instead of 500,000. It is not exponential and does not break lower bounds — it is a consequence of interference, not of “trying everything in parallel”.', 'Алгоритм Ґровера починається з рівномірної суперпозиції всіх N можливостей. Оракул позначає правильну відповідь фазою −1 (фазовий відкат), потім «дифузійний оператор» відбиває амплітуди відносно середнього. Після ~√N повторень імовірність правильної відповіді близька до 1.<br><br>Прискорення квадратичне: N = 10⁶ потребує ~1000 кроків замість 500 000. Це не експоненційно й не порушує нижніх меж — це наслідок інтерференції, а не паралельного «випробування всього».')
  },
  {
    id: 'shor', icon: '🔢', level: 16, keys: ['shor', 'period finding', 'шор', 'період'], codex: ['interf'],
    title: tr('Shor: faktorizácia cez hľadanie periódy', 'Shor: factoring through period finding', 'Шор: факторизація через пошук періоду'),
    short: tr('Shor nefaktorizuje priamo. Nájde periódu funkcie a² mod N, z ktorej sa dajú získať faktory.', 'Shor does not factor directly. It finds the period of a² mod N, from which the factors follow.', 'Шор не факторизує безпосередньо. Він знаходить період функції a² mod N, з якого випливають множники.'),
    body: tr('Klasická časť: zvoľ a, nájdi periódu r funkcie f(x) = aˣ mod N. Ak je r párne a a^(r/2) ≠ ±1, potom gcd(a^(r/2) ± 1, N) dá netriviálny faktor. Problém je, že nájsť r klasicky je také ťažké ako faktorizácia.<br><br>Kvantová časť: QFT prevedie periódu na merateľné frekvencie. Meranie dá násobok 1/r, z ktorého sa r odhadne reťazovým zlomkom. Celé je to polynomiálne v počte bitov — preto by Shor rozbil RSA, keby sme mali dosť stabilných qubitov.', 'The classical part: choose a, find the period r of f(x) = aˣ mod N. If r is even and a^(r/2) ≠ ±1, then gcd(a^(r/2) ± 1, N) gives a non-trivial factor. The problem is that finding r classically is as hard as factoring.<br><br>The quantum part: the QFT turns the period into measurable frequencies. A measurement gives a multiple of 1/r, from which r is estimated by a continued fraction. The whole thing is polynomial in the number of bits — that is why Shor would break RSA if we had enough stable qubits.', 'Класична частина: обери a, знайди період r функції f(x) = aˣ mod N. Якщо r парне й a^(r/2) ≠ ±1, то gcd(a^(r/2) ± 1, N) дає нетривіальний множник. Проблема в тому, що знайти r класично так само важко, як факторизувати.<br><br>Квантова частина: QFT перетворює період на вимірювані частоти. Вимірювання дає кратне 1/r, з якого r оцінюють ланцюговим дробом. Усе це поліноміально за кількістю бітів — тому Шор зламав би RSA, якби ми мали достатньо стабільних кубітів.')
  },
  {
    id: 'qec', icon: '🛡', level: 17, keys: ['korekcia chýb', 'error correction', 'qec', 'корекція помилок', 'код'], codex: ['cnot'],
    title: tr('Korekcia chýb: ako chrániť kvantovú informáciu', 'Error correction: how to protect quantum information', 'Корекція помилок: як захистити квантову інформацію'),
    short: tr('Jeden logický qubit rozložíme do viacerých fyzických. Syndrómové meranie zistí chybu bez čítania dát.', 'One logical qubit is spread over several physical ones. Syndrome measurement finds the error without reading the data.', 'Один логічний кубіт розподіляють на кілька фізичних. Синдромне вимірювання знаходить помилку, не читаючи дані.'),
    body: tr('Kvantovú informáciu nemožno kopírovať (no-cloning), preto sa korekcia robí inak: zapletie sa jeden logický qubit do viacerých fyzických. Bit-flip kód používa tri qubity |000⟩ a |111⟩; väčšinové meranie syndrómu prezradí, ktorý sa preklopil, bez toho, aby zistilo, či je stav |0⟩ alebo |1⟩.<br><br>Phase-flip kód je ten istý trik v báze |+⟩, |−⟩. Shorov 9-qubitový kód kombinuje oba a zvládne aj kombinované chyby. Dôležitý je prah: ak je fyzická chybovosť pod ním, korekcia sa vyplatí. Topologické qubity (Majorana) sa snažia chybu potlačiť už na úrovni hardvéru.', 'Quantum information cannot be copied (no-cloning), so correction works differently: one logical qubit is entangled across several physical ones. The bit-flip code uses three qubits |000⟩ and |111⟩; a majority syndrome measurement reveals which one flipped without finding out whether the state is |0⟩ or |1⟩.<br><br>The phase-flip code is the same trick in the |+⟩, |−⟩ basis. Shor’s 9-qubit code combines both and handles combined errors. The threshold matters: if the physical error rate is below it, correction pays off. Topological qubits (Majorana) try to suppress errors already in hardware.', 'Квантову інформацію не можна копіювати (no-cloning), тому корекція працює інакше: один логічний кубіт заплутують у кількох фізичних. Код bit-flip використовує три кубіти |000⟩ та |111⟩; мажоритарне вимірювання синдрому показує, який перевернувся, не з’ясовуючи, чи стан |0⟩, чи |1⟩.<br><br>Код phase-flip — той самий трюк у базисі |+⟩, |−⟩. 9-кубітний код Шора поєднує обидва й упорається з комбінованими помилками. Важливий поріг: якщо фізична частота помилок нижча за нього, корекція виправдана. Топологічні кубіти (Майорана) намагаються придушити помилки вже на рівні апаратури.')
  },
  {
    id: 'chemical-shift', icon: '🧬', level: 18, keys: ['chemick', 'chemical shift', 'j-väzb', 'j-coupl', 'хімічн', 'зв’яз'], codex: ['zeeman', 'B0', 'rabi'],
    title: tr('Chemický posun a J-väzba: molekula ako register', 'Chemical shift and J-coupling: a molecule as a register', 'Хімічний зсув і J-зв’язок: молекула як регістр'),
    short: tr('Okolie jadra mení jeho frekvenciu. J-väzba spája jadrá cez väzby a vytvára dvojqubitové hradlo.', 'A nucleus’s surroundings change its frequency. J-coupling links nuclei through bonds and gives a two-qubit gate.', 'Оточення ядра змінює його частоту. J-зв’язок з’єднує ядра через зв’язки й дає двокубітний гейт.'),
    body: tr('Chemický posun δ je malá zmena rezonančnej frekvencie spôsobená elektrónovým obalom. Každé jadro v molekule tak má vlastnú „adresu“ v spektre — preto sa dajú adresovať jednotlivé qubity.<br><br>J-väzba je nepriama interakcia cez kovalentné väzby. V spektre štiepi čiary na multiplety; v časovej doméne umožňuje dvojqubitové operácie (napr. CNOT cez sekvenciu RF impulzov a čakania). Molekula s viacerými jadrami je prirodzený kvantový register — výhoda NMR, ale aj dôvod, prečo je škálovanie ťažké.', 'The chemical shift δ is a small change of resonance frequency caused by the electron cloud. Each nucleus in a molecule thus has its own “address” in the spectrum — that is why individual qubits can be addressed.<br><br>J-coupling is an indirect interaction through covalent bonds. In the spectrum it splits lines into multiplets; in the time domain it enables two-qubit operations (e.g. CNOT via a sequence of RF pulses and delays). A molecule with several nuclei is a natural quantum register — an advantage of NMR, and also why scaling is hard.', 'Хімічний зсув δ — невелика зміна резонансної частоти, спричинена електронною оболонкою. Кожне ядро в молекулі має власну «адресу» в спектрі — тому окремі кубіти можна адресувати.<br><br>J-зв’язок — непряма взаємодія через ковалентні зв’язки. У спектрі він розщеплює лінії на мультиплети; у часовій області уможливлює двокубітні операції (наприклад, CNOT через послідовність РЧ-імпульсів і затримок). Молекула з кількома ядрами — природний квантовий регістр: перевага ЯМР, але й причина складного масштабування.')
  },
  {
    id: 'majorana', icon: '⚛', level: 19, keys: ['majoran', 'topolog', 'anyón', 'майоран', 'тополог'], codex: ['entangle'],
    title: tr('Majoranove fermióny: qubit ukrytý v topológii', 'Majorana fermions: a qubit hidden in topology', 'Ферміони Майорани: кубіт, схований у топології'),
    short: tr('Informácia je uložená nelokálne na koncoch drôtu. Lokálny šum ju nevidí, preto je odolnejšia.', 'Information is stored non-locally at the ends of a wire. Local noise cannot see it, so it is more robust.', 'Інформація зберігається нелокально на кінцях дроту. Локальний шум її не бачить, тому вона стійкіша.'),
    body: tr('V topologickom qubite sa qubit neukladá do jednej častice, ale do páru Majoranových nulových módov na koncoch nanodrótu. Lokálna porucha na jednom konci nemôže stav zmeniť, lebo informácia je rozložená medzi oboma koncami.<br><br>Hradlá sa robia <b>pletením</b> (braiding) týchto módov: keď obídeš jeden okolo druhého, stav sa transformuje. Pre neabelovské anyóny záleží na poradí — to je výpočet. Výzva je experimentálna: Majoranove módy sa ťažko vyrábajú a overujú. Ak by sa to podarilo, dostali by sme kvantový počítač s výrazne nižšou chybovosťou.', 'In a topological qubit the information is not stored in one particle but in a pair of Majorana zero modes at the ends of a nanowire. A local disturbance at one end cannot change the state, because the information is spread between both ends.<br><br>Gates are performed by <b>braiding</b> these modes: moving one around the other transforms the state. For non-Abelian anyons the order matters — that is the computation. The challenge is experimental: Majorana modes are hard to create and verify. If achieved, we would get a quantum computer with much lower error rates.', 'У топологічному кубіті інформація зберігається не в одній частинці, а в парі майоранівських нульових мод на кінцях нанодроту. Локальне збурення на одному кінці не може змінити стан, бо інформація розподілена між обома кінцями.<br><br>Гейти виконують <b>плетінням</b> (braiding) цих мод: коли обводиш одну навколо іншої, стан трансформується. Для неабелевих аніонів порядок має значення — це й є обчислення. Виклик експериментальний: майоранівські моди важко створити й перевірити. Якби це вдалося, ми отримали б квантовий комп’ютер із значно нижчою частотою помилок.')
  },
  {
    id: 'schmidt', icon: '🪞', level: 20, keys: ["schmidt", "teleport", "superhust", "superdense", "шмідт", "телепорт"], codex: ["schmidt", "ptrace", "entent", "nosignal"],
    title: tr("Schmidtov rozklad a čo previazanosť (ne)dovolí", "The Schmidt decomposition and what entanglement does (not) allow", "Розклад Шмідта і що заплутаність дозволяє (і ні)"),
    short: tr("Každý čistý stav dvoch systémov je Σ√λᵢ|uᵢ⟩|vᵢ⟩. Viac nenulových λᵢ = previazanosť; bez klasického kanála sa nič neprenesie.", "Every pure state of two systems is Σ√λᵢ|uᵢ⟩|vᵢ⟩. More non-zero λᵢ = entanglement; nothing is transmitted without a classical channel.", "Кожен чистий стан двох систем — Σ√λᵢ|uᵢ⟩|vᵢ⟩. Більше ненульових λᵢ = заплутаність; без класичного каналу нічого не передається."),
    body: tr("Stav |ψ⟩ = Σ cᵢⱼ|i⟩|j⟩ je produktový práve vtedy, keď sa matica C dá zapísať ako vonkajší súčin — pre dva qubity ad = bc. Singulárny rozklad C dá <b>Schmidtov rozklad</b> |ψ⟩ = Σ√λᵢ|uᵢ⟩|vᵢ⟩. Čiastočná stopa dá ρ<sub>A</sub> = Σλᵢ|uᵢ⟩⟨uᵢ| a entropia E = −Σλᵢ log₂λᵢ meria previazanosť (Bellov stav: 1 ebit).<br><br>Previazanosť nedovolí signalizovať: Bobova ρ<sub>B</sub> sa Aliciným meraním nezmení. Spolu s 2 klasickými bitmi však umožní <b>teleportáciu</b> neznámeho qubitu a naopak 1 qubit + zdieľaný pár prenesie 2 bity (<b>superhusté kódovanie</b>).", "A state |ψ⟩ = Σ cᵢⱼ|i⟩|j⟩ is a product state exactly when the matrix C is an outer product — for two qubits ad = bc. The singular value decomposition of C gives the <b>Schmidt decomposition</b> |ψ⟩ = Σ√λᵢ|uᵢ⟩|vᵢ⟩. The partial trace gives ρ<sub>A</sub> = Σλᵢ|uᵢ⟩⟨uᵢ| and the entropy E = −Σλᵢ log₂λᵢ measures entanglement (Bell state: 1 ebit).<br><br>Entanglement does not allow signalling: Bob’s ρ<sub>B</sub> does not change with Alice’s measurement. Together with 2 classical bits, however, it enables <b>teleportation</b> of an unknown qubit, and conversely 1 qubit + a shared pair carries 2 bits (<b>superdense coding</b>).", "Стан |ψ⟩ = Σ cᵢⱼ|i⟩|j⟩ добутковий саме тоді, коли матриця C — зовнішній добуток; для двох кубітів ad = bc. Сингулярний розклад C дає <b>розклад Шмідта</b> |ψ⟩ = Σ√λᵢ|uᵢ⟩|vᵢ⟩. Часткова слідова операція дає ρ<sub>A</sub> = Σλᵢ|uᵢ⟩⟨uᵢ|, а ентропія E = −Σλᵢ log₂λᵢ вимірює заплутаність (стан Белла: 1 ебіт).<br><br>Заплутаність не дозволяє сигналізувати: Бобова ρ<sub>B</sub> не змінюється від вимірювання Аліси. Але разом із 2 класичними бітами вона уможливлює <b>телепортацію</b> невідомого кубіта, і навпаки — 1 кубіт + спільна пара переносить 2 біти (<b>надщільне кодування</b>).")
  },
  {
    id: 'bell-nmr', icon: '📡', level: 21, keys: ["spinq", "tomograf", "pseudo", "singlet", "triplet", "томограф", "синглет"], codex: ["bellfour", "pps", "tomography", "jcoupling"],
    title: tr("Bellov stav na NMR: príprava a tomografia", "A Bell state on NMR: preparation and tomography", "Стан Белла на ЯМР: підготовка й томографія"),
    short: tr("H, voľný vývoj s J-väzbou a pulzy dajú Bellov stav; matica hustoty sa zrekonštruuje z 15 korelácií — ale len pseudo-čistá.", "H, free evolution under J-coupling and pulses give a Bell state; the density matrix is reconstructed from 15 correlations — but only pseudo-pure.", "H, вільна еволюція з J-зв’язком та імпульси дають стан Белла; матрицю густини відновлюють із 15 кореляцій — але лише псевдочисту."),
    body: tr("Na SpinQ (¹H a ³¹P, J ≈ 126 Hz) sa Bellov stav pripraví pulzom 90° (H), čakaním τ = 1/(2J) s J-väzbou (riadená fáza) a ďalšími pulzmi — spolu CNOT. Matica hustoty |Φ+⟩ má 4 rohové prvky ½ a korelácie ⟨XX⟩ = 1, ⟨YY⟩ = −1, ⟨ZZ⟩ = 1.<br><br>Pri izbovej teplote však ρ = (1−ε)I/4 + ε|ψ⟩⟨ψ| s ε ~ 10⁻⁵: <b>pseudo-čistý stav</b>, ktorý sa správa ako Bellov, ale nie je previazaný. <b>Tomografia</b> rekonštruuje všetkých 15 parametrov; fázu koherencie prezradí oneskorenie τ (φ = −2πJτ). Singlet |Ψ−⟩ je jediný stav so S = 0, ostatné tri tvoria triplet.", "On SpinQ (¹H and ³¹P, J ≈ 126 Hz) a Bell state is prepared by a 90° pulse (H), waiting τ = 1/(2J) under J-coupling (controlled phase) and further pulses — together a CNOT. The density matrix of |Φ+⟩ has 4 corner elements ½ and correlations ⟨XX⟩ = 1, ⟨YY⟩ = −1, ⟨ZZ⟩ = 1.<br><br>At room temperature, though, ρ = (1−ε)I/4 + ε|ψ⟩⟨ψ| with ε ~ 10⁻⁵: a <b>pseudo-pure state</b> that behaves like a Bell state but is not entangled. <b>Tomography</b> reconstructs all 15 parameters; the coherence phase is revealed by a delay τ (φ = −2πJτ). The singlet |Ψ−⟩ is the only state with S = 0, the other three form the triplet.", "На SpinQ (¹H і ³¹P, J ≈ 126 Гц) стан Белла готують імпульсом 90° (H), очікуванням τ = 1/(2J) з J-зв’язком (керована фаза) та іншими імпульсами — разом CNOT. Матриця густини |Φ+⟩ має 4 кутові елементи ½ і кореляції ⟨XX⟩ = 1, ⟨YY⟩ = −1, ⟨ZZ⟩ = 1.<br><br>Проте за кімнатної температури ρ = (1−ε)I/4 + ε|ψ⟩⟨ψ| з ε ~ 10⁻⁵: <b>псевдочистий стан</b>, що поводиться як стан Белла, але не заплутаний. <b>Томографія</b> відновлює всі 15 параметрів; фазу когерентності видає затримка τ (φ = −2πJτ). Синглет |Ψ−⟩ — єдиний стан із S = 0, решта три утворюють триплет.")
  },
  {
    id: 'phase-oracle', icon: '🔮', level: 22, keys: ["orákul", "oracle", "kickback", "spätný ráz", "оракул", "відкат"], codex: ["oracle", "interf", "relph", "globalph"],
    title: tr("Fázové orákulum a Deutschov algoritmus", "The phase oracle and Deutsch’s algorithm", "Фазовий оракул і алгоритм Дойча"),
    short: tr("Orákulum zapíše f(x) do znamienka. Interferencia (H) premení relatívnu fázu na merateľný výsledok — jedno volanie stačí na f(0) ⊕ f(1).", "The oracle writes f(x) into a sign. Interference (H) turns the relative phase into a measurable result — one call suffices for f(0) ⊕ f(1).", "Оракул записує f(x) у знак. Інтерференція (H) перетворює відносну фазу на вимірюваний результат — одного виклику досить для f(0) ⊕ f(1)."),
    body: tr("V Machovom–Zehnderovom interferometri rozhodne o výstupe len <b>relatívna</b> fáza ϕ medzi ramenami: P(0) = cos²(ϕ/2). Globálna fáza je nemerateľná. Orákulum U<sub>f</sub>|x⟩|y⟩ = |x⟩|y ⊕ f(x)⟩ s cieľom v |−⟩ vytvorí <b>fázový spätný ráz</b>: |x⟩ → (−1)<sup>f(x)</sup>|x⟩.<br><br>Deutschov algoritmus: |0⟩|1⟩ → H⊗H → U<sub>f</sub> → H na prvom qubite → meranie. Výsledok je f(0) ⊕ f(1): 0 pre konštantné f₀, f₁ (identita, NOT ako fáza je globálna), 1 pre vyvážené f₂, f₃. Klasicky treba dve volania.", "In a Mach–Zehnder interferometer only the <b>relative</b> phase ϕ between the arms decides the output: P(0) = cos²(ϕ/2). A global phase is unmeasurable. The oracle U<sub>f</sub>|x⟩|y⟩ = |x⟩|y ⊕ f(x)⟩ with the target in |−⟩ creates <b>phase kickback</b>: |x⟩ → (−1)<sup>f(x)</sup>|x⟩.<br><br>Deutsch’s algorithm: |0⟩|1⟩ → H⊗H → U<sub>f</sub> → H on the first qubit → measurement. The result is f(0) ⊕ f(1): 0 for the constant f₀, f₁ (their phase is global), 1 for the balanced f₂, f₃. Classically two calls are needed.", "В інтерферометрі Маха–Цендера вихід визначає лише <b>відносна</b> фаза ϕ між плечима: P(0) = cos²(ϕ/2). Глобальна фаза невимірювана. Оракул U<sub>f</sub>|x⟩|y⟩ = |x⟩|y ⊕ f(x)⟩ із ціллю в |−⟩ створює <b>фазовий відкат</b>: |x⟩ → (−1)<sup>f(x)</sup>|x⟩.<br><br>Алгоритм Дойча: |0⟩|1⟩ → H⊗H → U<sub>f</sub> → H на першому кубіті → вимірювання. Результат — f(0) ⊕ f(1): 0 для сталих f₀, f₁ (їхня фаза глобальна), 1 для збалансованих f₂, f₃. Класично потрібні два виклики.")
  },
  {
    id: 'walsh-hadamard', icon: '🎛', level: 23, keys: ["walsh", "jozs", "bernstein", "vazirani", "волш", "вазірані"], codex: ["walsh", "djalg", "bvalg", "querycost"],
    title: tr("Walshova–Hadamardova transformácia: DJ a BV", "The Walsh–Hadamard transform: DJ and BV", "Перетворення Волша–Адамара: DJ і BV"),
    short: tr("H<sup>⊗n</sup> rozloží f do znamienok (−1)<sup>x⋅y</sup>. Pre DJ ukáže, či je f konštantná; pre BV priamo prečíta skryté s — jedným dotazom.", "H<sup>⊗n</sup> decomposes f into the signs (−1)<sup>x⋅y</sup>. For DJ it shows whether f is constant; for BV it reads the hidden s directly — in one query.", "H<sup>⊗n</sup> розкладає f на знаки (−1)<sup>x⋅y</sup>. Для DJ показує, чи f стала; для BV прямо зчитує приховане s — одним запитом."),
    body: tr("H<sup>⊗n</sup>|x⟩ = 2<sup>−n/2</sup> Σ<sub>y</sub> (−1)<sup>x⋅y</sup>|y⟩. Obvod H<sup>⊗n</sup> → fázové orákulum → H<sup>⊗n</sup> dá amplitúdy A<sub>f</sub>(y) = 2<sup>−n</sup> Σ<sub>x</sub> (−1)<sup>f(x) ⊕ x⋅y</sup>.<br><br><b>Deutsch–Jozsa</b>: A<sub>f</sub>(0…0) = ±1 pre konštantnú f, 0 pre vyváženú — jeden dotaz namiesto 2<sup>n−1</sup>+1 deterministických. <b>Bernstein–Vazirani</b>: pre f(x) = s⋅x je A<sub>f</sub>(s) = 1, takže meranie vráti s; klasicky treba n dotazov. Ide o <b>zložitosť dotazov</b> — na reálnom hardvéri sa hradlá skladajú z tvarovaných pulzov (optimálne riadenie) a šum obmedzuje hĺbku obvodu.", "H<sup>⊗n</sup>|x⟩ = 2<sup>−n/2</sup> Σ<sub>y</sub> (−1)<sup>x⋅y</sup>|y⟩. The circuit H<sup>⊗n</sup> → phase oracle → H<sup>⊗n</sup> gives the amplitudes A<sub>f</sub>(y) = 2<sup>−n</sup> Σ<sub>x</sub> (−1)<sup>f(x) ⊕ x⋅y</sup>.<br><br><b>Deutsch–Jozsa</b>: A<sub>f</sub>(0…0) = ±1 for a constant f, 0 for a balanced one — one query instead of 2<sup>n−1</sup>+1 deterministic ones. <b>Bernstein–Vazirani</b>: for f(x) = s⋅x, A<sub>f</sub>(s) = 1, so the measurement returns s; classically n queries are needed. This is <b>query complexity</b> — on real hardware gates are built from shaped pulses (optimal control) and noise limits the circuit depth.", "H<sup>⊗n</sup>|x⟩ = 2<sup>−n/2</sup> Σ<sub>y</sub> (−1)<sup>x⋅y</sup>|y⟩. Схема H<sup>⊗n</sup> → фазовий оракул → H<sup>⊗n</sup> дає амплітуди A<sub>f</sub>(y) = 2<sup>−n</sup> Σ<sub>x</sub> (−1)<sup>f(x) ⊕ x⋅y</sup>.<br><br><b>Дойч–Йожа</b>: A<sub>f</sub>(0…0) = ±1 для сталої f, 0 для збалансованої — один запит замість 2<sup>n−1</sup>+1 детермінованих. <b>Бернштейн–Вазірані</b>: для f(x) = s⋅x A<sub>f</sub>(s) = 1, тож вимірювання повертає s; класично потрібно n запитів. Ідеться про <b>складність запитів</b> — на реальному обладнанні гейти складаються з профільованих імпульсів (оптимальне керування), а шум обмежує глибину схеми.")
  },
  {
    id: 'cat-qubit', icon: '🐈', level: 24, keys: ["mačac", "cat qubit", "zenón", "zeno", "котяч", "зенон", "buffer", "буфер"], codex: ["catqubit", "twophoton", "biasnoise", "zeno"],
    title: tr("Mačacie qubity: prostredie ako strážca", "Cat qubits: the environment as a guard", "Котячі кубіти: середовище як вартовий"),
    short: tr("|±α⟩ v rezonátore, chránené dvojfotónovou disipáciou. Bit-flipy ~e<sup>−2n̄</sup>, fázové chyby ~n̄ — opravuje sa už len fáza.", "|±α⟩ in a resonator, protected by two-photon dissipation. Bit-flips ~e<sup>−2n̄</sup>, phase errors ~n̄ — only the phase needs correcting.", "|±α⟩ у резонаторі, захищені двофотонною дисипацією. Bit-flip ~e<sup>−2n̄</sup>, фазові помилки ~n̄ — виправляють лише фазу."),
    body: tr("Mačací qubit kóduje |0<sub>L</sub>⟩ ≃ |α⟩, |1<sub>L</sub>⟩ ≃ |−α⟩. Lindbladov člen κ₂D[a² − α²] (rezervoárové inžinierstvo) ťahá každý stav späť do podpriestoru bez dekoherencie ker(a² − α²). Na preklopenie |α⟩ → |−α⟩ by šum musel prejsť celý fázový priestor: Γ<sub>bit</sub> ∝ e<sup>−2n̄</sup>. Strata fotónu však zamení mačacie stavy a|C±⟩ ∝ |C∓⟩ — fázová chyba, Γ<sub>phase</sub> ∝ n̄.<br><br>Hradlá využívajú <b>kvantový Zenónov jav</b>: slabý pohon ε(a + a†) sa disipáciou premietne na 2ħεα Z<sub>L</sub> (θ = 4εαt). Disipáciu fyzicky vyrobí <b>buffer</b> b spojený s pamäťou a cez H<sub>int</sub> = ħg₂(a²b† + a†²b), κ₂ ≈ 4|g₂|²/κ<sub>b</sub>. Odhad (Pappalardo 2026): RSA-2048 za 3,14 dňa s 22 593 fyzickými qubitmi — za predpokladu bit-flipu ~100 rokov.", "The cat qubit encodes |0<sub>L</sub>⟩ ≃ |α⟩, |1<sub>L</sub>⟩ ≃ |−α⟩. The Lindblad term κ₂D[a² − α²] (reservoir engineering) pulls every state back into the decoherence-free subspace ker(a² − α²). To flip |α⟩ → |−α⟩ the noise would have to cross the whole phase space: Γ<sub>bit</sub> ∝ e<sup>−2n̄</sup>. Photon loss, however, swaps the cat states a|C±⟩ ∝ |C∓⟩ — a phase error, Γ<sub>phase</sub> ∝ n̄.<br><br>Gates use the <b>quantum Zeno effect</b>: a weak drive ε(a + a†) is projected by the dissipation to 2ħεα Z<sub>L</sub> (θ = 4εαt). The dissipation is physically built by a <b>buffer</b> b coupled to the memory a via H<sub>int</sub> = ħg₂(a²b† + a†²b), κ₂ ≈ 4|g₂|²/κ<sub>b</sub>. Estimate (Pappalardo 2026): RSA-2048 in 3.14 days with 22 593 physical qubits — assuming a bit-flip time of ~100 years.", "Котячий кубіт кодує |0<sub>L</sub>⟩ ≃ |α⟩, |1<sub>L</sub>⟩ ≃ |−α⟩. Член Ліндблада κ₂D[a² − α²] (резервуарна інженерія) тягне кожен стан назад у підпростір без декогеренції ker(a² − α²). Щоб перевернути |α⟩ → |−α⟩, шум мав би перетнути весь фазовий простір: Γ<sub>bit</sub> ∝ e<sup>−2n̄</sup>. Втрата фотона ж міняє котячі стани a|C±⟩ ∝ |C∓⟩ — фазова помилка, Γ<sub>phase</sub> ∝ n̄.<br><br>Гейти використовують <b>квантовий ефект Зенона</b>: слабке накачування ε(a + a†) дисипацією проєктується в 2ħεα Z<sub>L</sub> (θ = 4εαt). Дисипацію фізично створює <b>буфер</b> b, з’єднаний із пам’яттю a через H<sub>int</sub> = ħg₂(a²b† + a†²b), κ₂ ≈ 4|g₂|²/κ<sub>b</sub>. Оцінка (Паппалардо 2026): RSA-2048 за 3,14 доби з 22 593 фізичними кубітами — за умови часу bit-flip ~100 років.")
  },
];

// predvolené hlbšie vysvetlenie pre level (keď sa pojem nedá rozpoznať z textu)
const LEVEL_DEEP = {
  1: 'amplitude', 2: 'measurement', 3: 'bloch', 4: 'superposition-mixture', 5: 'braket', 6: 'nmr',
  7: 'entanglement', 8: 'complementarity', 9: 'bloch', 10: 'purity', 11: 'mid-circuit', 12: 'pulse',
  13: 'measurement', 14: 'entanglement', 15: 'qft', 16: 'grover', 17: 'qec', 18: 'chemical-shift', 19: 'majorana',
  20: 'schmidt', 21: 'bell-nmr', 22: 'phase-oracle', 23: 'walsh-hadamard', 24: 'cat-qubit',
};

const Explain = {
  all() { return EXPLAIN; },
  get(id) { return EXPLAIN.find((e) => e.id === id) || null; },
  forText(text) {
    const s = String(text || '').replace(/<[^>]+>/g, ' ').toLowerCase();
    if (!s.trim()) return null;
    let best = null, score = 0;
    for (const e of EXPLAIN) {
      let n = 0;
      for (const k of e.keys) if (s.includes(k.toLowerCase())) n += k.length > 4 ? 2 : 1;
      if (n > score) { score = n; best = e; }
    }
    return best;
  },
  forQuestion(q) {
    if (!q) return null;
    if (q.explain) return this.get(q.explain);
    const found = this.forText([q.q, q.why, q.ctx, ...(q.options || [])].join(' '));
    return found || this.get(LEVEL_DEEP[q.lvl]) || null;
  },
  forCodex(id) {
    return EXPLAIN.find((e) => (e.codex || []).includes(id)) || null;
  },
  // hlbšie vysvetlenie pre kartu Kódexu: vlastné, alebo vygenerované z textu karty
  codex(id) {
    const c = CODEX.find((e) => e.id === id);
    if (!c) return null;
    const own = this.forCodex(id);
    if (own) return own;
    return {
      id: 'codex:' + id, icon: c.sym, level: c.level, generated: true,
      title: c.name,
      short: tr('Karta z Kódexu — tu je rozšírené vysvetlenie.', 'A Codex card — here is the expanded explanation.', 'Картка з Кодексу — ось розширене пояснення.'),
      body: c.text + (c.do ? `<br><br><b>${tr('Používaj', 'Use', 'Використовуй')}:</b> ${c.do}` : '') + (c.dont ? `<br><b>${tr('Nepleť si', 'Do not confuse', 'Не плутай')}:</b> ${c.dont}` : ''),
    };
  },
  open(id) {
    let ex = this.get(id);
    if (!ex && String(id).startsWith('codex:')) ex = this.codex(String(id).slice(6));
    if (!ex) return;
    this.current = ex;
    const body = $('#explain .body');
    const lvl = ex.level ? tr(`Level ${ex.level}`, `Level ${ex.level}`, `Рівень ${ex.level}`) : '';
    body.innerHTML = `<div class="deep-head"><span class="deep-ico">${ex.icon || '📚'}</span><div><h2>${ex.title}</h2><div class="deep-meta">${lvl}${ex.generated ? ' · ' + tr('Kódex', 'Codex', 'Кодекс') : ''}</div></div></div>`
      + `<p class="deep-short">${ex.short || ''}</p>`
      + `<div class="deep-body">${annotate(ex.body || '', false, true)}</div>`;
    // súvisiace pojmy: klik = ďalšie hlbšie vysvetlenie
    const rel = (ex.codex || []).map((id) => CODEX.find((c) => c.id === id)).filter(Boolean).slice(0, 4);
    if (rel.length) {
      const box = el('div', 'deep-rel');
      box.appendChild(el('b', null, tr('Súvisí', 'Related', 'Пов’язане')));
      for (const c of rel) {
        const b = el('button', 'relbtn', `${c.sym} ${c.name}`);
        b.dataset.tip = tr('Otvoriť hlbšie vysvetlenie.', 'Open a deeper explanation.', 'Відкрити глибше пояснення.');
        b.onclick = () => Explain.open('codex:' + c.id);
        box.appendChild(b);
      }
      body.appendChild(box);
    }
    const row = el('div', 'row deep-actions');
    if (ex.level) {
      const p = el('button', 'primary', tr('🧪 Precvičiť level', '🧪 Practise the level', '🧪 Потренувати рівень'));
      p.onclick = () => { Explain.close(); if (UI.busy) return UI.toast(tr('Najprv dokonči rozhovor.', 'Finish the conversation first.', 'Спершу заверши розмову.')); Learn.testMe(ex.level); };
      row.appendChild(p);
    }
    const cb = el('button', null, tr('📖 Kódex', '📖 Codex', '📖 Кодекс'));
    cb.onclick = () => { Explain.close(); UI.toggleCodex(true); };
    row.appendChild(cb);
    row.appendChild(UI.askButton(`${ex.title}\n${ex.short}\n${ex.body || ''}`));
    body.appendChild(row);
    const o = $('#explain');
    if (!o.classList.contains('show')) { Sound.sfx('codex'); o.classList.add('show'); }
    if (typeof Progress !== 'undefined') Progress.onExplain(ex);
  },
  close() { const o = $('#explain'); if (o.classList.contains('show')) { o.classList.remove('show'); Sound.sfx('close'); } },
  button(ex) {
    if (!ex) return null;
    const b = el('button', 'deepbtn', tr('📚 Hlbšie', '📚 Go deeper', '📚 Глибше'));
    b.dataset.tip = tr('Rozšírené vysvetlenie tohoto pojmu — bez toho, aby si opustil(a) rozhovor.', 'An expanded explanation of this concept — without leaving the conversation.', 'Розширене пояснення цього поняття — не залишаючи розмову.');
    b.onclick = (e) => { e.stopPropagation(); Explain.open(ex.id); };
    return b;
  },
};

// klik na podčiarknutý pojem = hlbšie vysvetlenie (tooltip zostáva pri prejdení myšou)
document.addEventListener('click', (e) => {
  const t = e.target.closest && e.target.closest('.term');
  if (!t || e.ctrlKey || e.metaKey || e.shiftKey) return;
  const ex = Explain.forText(t.textContent + ' ' + (t.dataset.tip || ''));
  if (ex) { e.preventDefault(); Explain.open(ex.id); }
});
